import sys
from math import gcd

def main():
    n, m = map(int, sys.stdin.read().strip().split())
    table = [['A'] * m for _ in range(n)]
    g = gcd(n, m)
    for i in range(n):
        for j in range(m):
            table[i][j] = chr(ord('A') + (i // (n // g)) * g + (j // (m // g)))
    for row in table:
        print(''.join(row))

main()
